const fs=require('node:fs/promises');
const assert=require('node:assert/strict');
const {chromium}=require('playwright-core');
const {makeSave}=require('../v76/fixtures.cjs');
const url=process.argv[2]||'http://127.0.0.1:8795';
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 try{
  const page=await browser.newPage({viewport:{width:Number(process.env.TAKDEX_WIDTH)||412,height:860},isMobile:true,hasTouch:true,reducedMotion:'reduce',ignoreHTTPSErrors:true});
  page.setDefaultTimeout(18000);
  const errors=[];page.on('pageerror',e=>errors.push(e.stack));
  await page.goto(url,{waitUntil:'domcontentloaded'});
  await page.evaluate(()=>{
   teams.push({id:'v77-test',name:'V77 test',game:'Black 2',pokemon:Array(6).fill(null)});
   save();showTeams();openTeam('v77-test');
  });
  const picker=page.locator('[data-save-file="v77-test"]');
  await page.locator('[data-td41-team-plan="v77-test"]').click();
  assert.match(await page.locator('#td77ActualProgress').textContent(),/Not synchronized/);
  await page.locator('#td4Back').click();
  const file=(seq,progress)=>({name:'story.sav',mimeType:'application/octet-stream',buffer:makeSave(23,seq,40,progress)});
  await picker.setInputFiles(file(21,{mask:1}));
  await page.waitForFunction(()=>current?.saveLink?.progression?.badgeCount===1);
  const update=await page.evaluate(bytes=>takDexSaveSync.synchronize({teamId:'v77-test',bytes:Uint8Array.from(atob(bytes),c=>c.charCodeAt(0))}),file(22,{mask:7,surf:true}).buffer.toString('base64'));
  assert.equal(update,'updated');
  assert.equal(await page.evaluate(()=>current.saveLink.progression.badgeCount),3);
  await picker.setInputFiles({name:'story.sav',mimeType:'application/octet-stream',buffer:Buffer.alloc(524288)});
  await page.waitForFunction(()=>document.querySelector('[data-save-status="v77-test"]').textContent.includes('No valid'));
  assert.equal(await page.evaluate(()=>current.saveLink.progression.badgeCount),3);
  await page.locator('[data-td41-team-plan="v77-test"]').click();
  await page.locator('#td77ActualProgress').filter({hasText:'3/8'}).waitFor();
  assert.equal(await page.locator('#td77Availability').inputValue(),'pre-league');
  await page.locator('#td77Availability').selectOption('badge-8');
  assert.equal(await page.evaluate(()=>current.saveLink.progression.badgeCount),3);
  await page.locator('#td4Slots [data-td4-slot="1"]').click();
  const candidate=page.locator('[data-td4-candidate]').first();
  await candidate.waitFor();
  assert.equal(await page.locator('#td77Availability').inputValue(),'badge-8');
  assert.equal(await page.locator('#td77Legendary').isChecked(),false);
  assert.equal(await page.locator('[data-td4-candidate]').filter({hasText:/Zekrom|Kyurem|Reshiram/}).count(),0);
  await candidate.click();
  await page.locator('[data-td63-manual-select]').waitFor();
  await page.waitForFunction(()=>Math.abs(document.querySelector('#td63ManualCandidate').getBoundingClientRect().top)<110);
  await page.locator('[data-td63-manual-select]').click();
  await page.waitForFunction(()=>JSON.parse(localStorage.getItem('takdex-v74-playthrough-plans'))['Black 2:v77-test']?.slots[1]?.plannedMoves?.filter(m=>m.move).length===4);
  const selectedName=await page.evaluate(()=>JSON.parse(localStorage.getItem('takdex-v74-playthrough-plans'))['Black 2:v77-test'].slots[1].name);
  await candidate.waitFor();
  assert.ok(!(await page.locator('[data-td4-candidate] strong').allTextContents()).map(s=>s.toLowerCase().replace(/ /g,'-')).includes(selectedName));
  await page.locator('#td77Lock').click();
  await page.evaluate(()=>td41OpenTeamPlan('v77-test'));
  await page.locator('#td77Lock').waitFor();
  assert.equal(await page.locator('#td77Lock').getAttribute('aria-pressed'),'true');
  assert.equal(await page.locator('[data-view="actual"]').count(),0);
  await page.locator('[data-view="during"]').click();
  assert.equal(await page.locator('[data-td77-during]').count(),4);
  assert.equal(await page.locator('.td77-during-flow .td42-arrow').count(),4);
  const duringField=page.locator('[data-td77-during]').first();
  const original=await duringField.inputValue();
  await duringField.click();
  const choices=duringField.locator('..').locator('[data-td45-pick]');
  const other=choices.filter({hasNotText:original}).first();
  if(await other.count())await other.click();
  const duringValue=await duringField.inputValue();
  await page.locator('[data-view="final"]').click();
  assert.equal(await page.locator('#td41MoveSlots [data-td45-move]').count(),4);
  await page.locator('#battleTab').click();
  await page.locator('#teamsTab').click();
  assert.equal(await page.locator('#td4TeamPlannerPage').isVisible(),true);
  assert.equal(await page.locator('#td77Availability').inputValue(),'badge-8');
  await page.locator('[data-view="during"]').click();
  assert.equal(await page.locator('[data-td77-during]').first().inputValue(),duringValue);
  await page.locator('[data-view="final"]').click();
  for(const id of ['td4Coverage','td4HM','td77Gyms','td4League']){
   const section=page.locator('#'+id).locator('..');
   assert.equal(await section.evaluate(el=>el.open),false);
   assert.ok((await section.locator('summary').first().textContent()).trim());
  }
  assert.equal(await page.locator('#td77Improvements').locator('..').evaluate(el=>el.open),false);
  await page.locator('#td77Improvements').locator('..').locator('summary').first().click();
  assert.equal(await page.locator('#td77Improvements').isVisible(),true);

  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  await page.locator('#td77Lock').click();
  const settings=page.locator('#td4Edit .td42-settings').first();
  if(!await settings.evaluate(el=>el.open))await settings.locator(':scope > summary').click();
  await candidate.waitFor();
  const openComparison=async(method,button=page.locator('[data-td4-candidate]').first())=>{
   await button.scrollIntoViewIfNeeded();
   const box=await button.boundingBox(),x=box.x+box.width/2,y=box.y+box.height/2;
   if(method==='mouse'){
    await page.mouse.move(x,y);await page.mouse.down();await page.waitForTimeout(550);await page.mouse.up();
   }else{
    const cdp=await page.context().newCDPSession(page);
    await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x,y}]});
    await page.waitForTimeout(550);
    await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
    await cdp.detach();
   }
   const dialog=page.locator('dialog[open].td71-quick-dialog');
   assert.match(await dialog.textContent(),/Compare/);
   assert.equal(await page.locator('#td4TeamPlannerPage').isVisible(),true);
   await dialog.locator('[data-compare-confirm]').click();
   assert.equal(await page.locator('#td56Game').inputValue(),'Black 2');
   await page.locator('#td56Back').click();
   assert.equal(await page.locator('#td4TeamPlannerPage').isVisible(),true);
  };
  await openComparison('mouse');
  await candidate.click();
  await openComparison('touch',page.locator('[data-td63-manual-select]'));
  console.log('Team Planner comparison opened and returned for mouse and emulated touch');
  await page.locator('#td4Back').click();
  assert.equal(await page.locator('#td4TeamPlannerPage').isVisible(),false);
  const download=page.waitForEvent('download');
  await page.locator('[data-export-card="v77-test"]').click();
  const contents=await fs.readFile(await (await download).path());
  const payload=JSON.parse(contents);
  assert.equal(payload.version,2);
  assert.equal(payload.progression.badgeCount,3);
  assert.equal(payload.plan.slots[1].duringMoves.length,4);
  const imported=await browser.newPage();
  await imported.goto(url,{waitUntil:'domcontentloaded'});
  await imported.locator('#importTeamFile').setInputFiles({name:'team.json',mimeType:'application/json',buffer:contents});
  await imported.waitForFunction(()=>JSON.parse(localStorage.getItem('poketact-teams'))?.length===1);
  const restored=await imported.evaluate(()=>{
   const team=JSON.parse(localStorage.getItem('poketact-teams'))[0];
   return {team,plan:JSON.parse(localStorage.getItem('takdex-v74-playthrough-plans'))[team.game+':'+team.id]};
  });
  assert.notEqual(restored.team.id,'v77-test');
  assert.deepEqual(restored.plan,payload.plan);
  assert.equal(restored.team.saveLink.exportedSnapshot,true);
  await imported.close();
  console.log('Global During game and Final modes with Actual comparison, independent summaries, export/import into separate storage and new ID');

  console.log('Progression-only sync, invalid preservation, hypothetical milestone, empty-slot preview and four-move population, persisted lock');
  await page.locator('#dexTab').click();
  await page.evaluate(()=>takDexBattleNavigationV73.showDex('lapras','dex',{game:'Black 2',id:131}));
  await page.locator('#td77DexAbility option').nth(1).waitFor({state:'attached'});
  assert.equal(await page.locator('#td77DexAbility').inputValue(),'');
  await page.locator('#td77DexAbility').selectOption('hydration');
  assert.equal(await page.locator('#td77HiddenAbility').isVisible(),true);
  const encounters=page.locator('#td56DexEncounters');
  if(!await encounters.evaluate(el=>el.open))await encounters.locator('summary').click();
  await encounters.locator('[data-td74-dex-map="Village Bridge"]').first().click();
  assert.equal(await page.locator('#mapsGame').inputValue(),'Black 2');
  await page.waitForFunction(()=>document.querySelector('#mapsCanvas svg')?.dataset.selection?.toLowerCase().includes('village'));
  assert.match(await page.locator('#backMaps').textContent(),/Back/);
  assert.equal(await page.locator('.td73-map-toolbar #backMaps').count(),1);
  await page.locator('#backMaps').click();
  assert.equal(await encounters.evaluate(el=>el.open),true);
  console.log('Pokédex hidden ability and Black 2 Village Bridge map with return state');
  await page.evaluate(()=>takDexBattleNavigationV73.showDex('rotom','dex',{game:'Black',id:479}));
  await page.locator('#td77DexAbility').waitFor();
  assert.equal(await page.locator('#td77DexAbility').inputValue(),'levitate');
  await page.evaluate(()=>takDexBattleNavigationV73.showDex('pikachu','dex',{game:'Red',id:25}));
  await page.locator('#dexResult .td71-dex-hero').filter({hasText:'Red'}).waitFor();
  assert.equal(await page.locator('#td77DexAbility').count(),0);
  assert.equal(await page.locator('#dexTeam,#dexTeamPoke,#td73DexSelector summary').count(),0);
  await page.locator('#dexGame').selectOption('All Games');
  await page.locator('#dexInput').fill('fr');
  await page.locator('#dexResults button').first().waitFor();
  assert.ok(await page.locator('#dexResults button').count()>1);
  assert.equal(await page.locator('#dexResults').evaluate(el=>{
   const box=el.getBoundingClientRect();
   return document.elementFromPoint(box.left+12,box.top+Math.min(42,box.height/2))?.closest('#dexResults')===el;
  }),true);
  assert.equal(await page.locator('#dexSearch').count(),0);
  await page.locator('#dexResults button').first().click();
  await page.locator('#dexResult .td71-dex-hero').filter({hasNotText:'Pikachu'}).waitFor();
  await page.locator('#openTypeExplorer').click();
  await page.locator('#typeExplorerGame').selectOption('Black 2');
  await page.locator('[data-explore-type="fire"]').click();
  await page.locator('#typeExplorerResults .td61-entry').first().waitFor();
  await page.waitForFunction(()=>document.querySelector('#typeExplorerResults .td61-entry').getBoundingClientRect().top<100);
  console.log('Generation I Pokédex hides abilities and selecting a type scrolls to results');
  assert.deepEqual(errors,[]);
 }finally{await browser.close();}
})().catch(error=>{console.error(error);process.exitCode=1});
